from lib import *
S = SS('w4')
steps = [
    step("ARP 缓存就是“邻居表”:本机 en0 上 arp -an 记着 81 条已解析的邻居(同一网段的设备),每条是 IP → MAC。netstat -rn 里默认网关的主机路由标志是 UHLWIir(U 可用、H 主机路由、L 带链路层地址、W 由 ARP 自动生成、I 接口作用域、i 地址已完成),Expire 剩余 1180 秒;5 秒后是 1199 秒——没有单调倒计时,因为这期间有流量用到了这条邻居,系统刷新了寿命。系统参数 net.link.ether.inet.max_age=1200(寿命 20 分钟)、maxtries=5(最多发 5 次请求)、host_down_time=20。", t=tl(S(1)), mark=lidx(S(1), 'UHLWIir', '5 秒之后'), done=lidx(S(1), 'arp -an 在 en0 上', '系统参数'), b=bars([['arp -an 邻居数', 81, '81 条'], ['max_age', 1200, '1200 s'], ['网关 Expire 剩余', 1180, '1180 s']], 1200, mark=[2], done=[0, 1]), kv=KV([['邻居表', '81 条'], ['max_age', '1200 秒'], ['maxtries', '5 次']], ['max_age'])),
    step("一次完整的 ARP 解析(挑了同网段一台在线、但本机缓存里没有的主机,ping 它时抓 ARP):请求是一个 42 字节的以太网广播帧(目的 ff:ff:ff:…,EtherType 0x0806),ARP 报文本体 28 字节:硬件类型 1(以太网)、协议类型 0x0800(IPv4)、硬件地址长 6、协议地址长 4、操作 1(who-has);发送方 MAC/IP 是本机,目标 MAC 全 0(未知)、目标 IP 是那台主机。93.53 ms 后应答来了:60 字节单播帧,操作 2(is-at),发送方 MAC 是对方的。解析完,对方 MAC 进入本机缓存,ping 才真正发出。", t=tl(S(2)), mark=lidx(S(2), '请求  帧长 42', '应答  帧长 60'), done=lidx(S(2), 'ARP: 硬件类型'), b=bars([['请求帧', 42, '42 B 广播'], ['应答帧', 60, '60 B 单播'], ['请求→应答', 93.53, '93.53 ms']], 60, mark=[2], done=[0, 1]), kv=KV([['请求', '广播,目标 MAC 全 0'], ['应答', '单播,带上对方 MAC'], ['结果', '写入邻居表,然后才发 ICMP']], ['结果'])),
    step("没人应答时(每秒 ping 一个不存在的同网段地址,共 8 秒):本机发出 5 个 ARP 请求,时刻 0、1.01、2.01、3.01、4.02 秒——正好每秒一个,到 maxtries=5 就不再发;ping 一路 Request timeout;arp -an 里这个地址的状态是 (incomplete)。邻居表里留下一个“未完成”的条目,告诉内核这个地址正在解析、暂时不通。", t=tl(S(3)), mark=lidx(S(3), '本机发出的 ARP 请求 5 个', 'incomplete'), done=lidx(S(3), 'ping 的输出'), b=bars([['0 s', 1, '请求 1'], ['1.01 s', 2, '请求 2'], ['2.01 s', 3, '请求 3'], ['3.01 s', 4, '请求 4'], ['4.02 s', 5, '请求 5']], 5, mark=[4], done=[0, 1, 2, 3]), kv=KV([['无应答', '每秒 1 个请求'], ['次数', '最多 maxtries=5 个'], ['条目状态', '(incomplete)']], ['条目状态'])),
    step("这个网段 30 秒里的 ARP 流量:共 168 个 ARP 帧,请求 166 个(全是广播,所以连别的设备之间的请求本机也看得到),应答只抓到 2 个(应答是单播,通常只送到提问者,抓包点看不到别人收到的);其中免费 ARP(发送方 IP = 目标 IP,用来宣告自己的地址/刷新别人的缓存)12 个,ARP 探测(发送方 IP = 0.0.0.0,用来检测地址冲突)7 个。配上对的 2 对请求 → 应答延迟 0.09 ms。", t=tl(S(4)), mark=lidx(S(4), '30 秒共 168 个', '配上对的'), done=lidx(S(4), '应答只抓到'), b=bars([['请求(广播)', 166, '166'], ['应答(单播)', 2, '2'], ['免费 ARP', 12, '12'], ['ARP 探测', 7, '7']], 166, mark=[1], done=[0, 2, 3]), kv=KV([['请求', '广播,整个网段都看得到'], ['应答', '单播,多数看不到'], ['免费 ARP / 探测', '12 / 7 个']], ['免费 ARP / 探测'])),
    step("发给自己和环回不需要 ARP:ping 127.0.0.1 和 ping 本机自己的 en0 地址,同时在 en0 和 lo0 上抓:en0 上与本机地址相关的 ARP 帧 0 个,lo0 上非 IP 的帧(ARP 或别的)0 个。发往本机自己地址的包走本机内部的 lo0,不会出网卡,所以也不用问“这个 IP 的 MAC 是谁”。", t=tl(S(5)), mark=lidx(S(5), 'en0 上与本机地址'), done=lidx(S(5), 'en0 上与本机地址'), kv=KV([['ping 127.0.0.1', '不出网卡,无 ARP'], ['ping 本机 en0 地址', '同样走 lo0,无 ARP'], ['需要 ARP 的', '同网段的别的主机']], ['需要 ARP 的'])),
]
A = mkartw('w4', 4, '网络协议,ARP,邻居表,免费ARP,tcpdump,真实验证,动画演示',
    '在真实以太网上看 ARP:邻居表 81 条、网关路由标志 UHLWIir、max_age 1200 s;一次完整解析是 42 字节广播请求 + 60 字节单播应答(93.53 ms);无人应答时每秒重发一个请求、共 5 个,条目停在 (incomplete);30 秒的网段流量里请求 166 个(广播)、应答只抓到 2 个,免费 ARP 12 个、探测 7 个;发往本机自己地址不需要 ARP。',
    'IP 地址要变成 MAC 才能发出帧,这一步靠 ARP。邻居表里存着什么、请求和应答在线上长什么样、没人应答时会怎样重试、网段里每分钟有多少 ARP 在跑?这篇用 tcpdump 抓真实网段,并看 macOS 的邻居表。',
    [('42 → 60', 'ARP 请求(广播)与应答(单播)的帧长;应答在 93.53 ms 后到达'), ('5 个 / 1 秒', '无人应答时 ARP 请求的次数与间隔(maxtries=5)'), ('166 vs 2', '30 秒网段里抓到的 ARP 请求与应答——请求是广播,应答是单播')],
    [('邻居表', '<p>每条记录是 IP → MAC,带寿命(macOS 的 max_age 是 1200 秒);netstat -rn 里 ARP 学来的条目标志含 W 和 L。</p>'),
     ('请求与应答', '<p>请求是广播帧,目标 MAC 全 0;应答是单播,带上对方的 MAC。ARP 报文本体 28 字节,放在 14 字节的以太网头后面。</p>'),
     ('没人应答', '<p>内核每秒重发一次请求,最多 maxtries=5 次,条目停在 (incomplete);再往这个地址发包会立刻失败。</p>'),
     ('网段里的 ARP', '<p>广播的请求整个网段都听得到;免费 ARP 和探测用于宣告 / 检测地址冲突。</p>'),
     ('不需要 ARP 的情形', '<p>发给本机自己的地址走 lo0,不会出网卡,也就没有 ARP。</p>')],
    steps,
    [ENV_W + '。邻居表通过 sysd.py(系统 python 常驻进程)执行 arp / netstat,因为从 Homebrew python 起的子进程会被 macOS 的本地网络隐私限制看不到邻居表;MAC 地址只保留前 3 字节;第二节挑的是同网段一台在线的主机,第四节抓的是整个网段的 ARP(包含别的设备之间的),只统计数量',
     '没有验证:ARP 欺骗 / 缓存投毒(没有原始包注入权限);代理 ARP;ARP 老化时的单播探测(NUD)细节;IPv6 的邻居发现(见 NDP 一篇);交换机的 ARP 检测;不同操作系统对 incomplete 条目的处理'],
    'ARP')
